# ---------- um assunto por planeta (gerado da tabela da lore) ----------
L_pt=json.load(open('src/main/resources/assets/lanterna/lang/pt_br.json',encoding='utf-8'))
L_en=json.load(open('src/main/resources/assets/lanterna/lang/en_us.json',encoding='utf-8'))
P=[("oa","Oa","Verde","Green","vontade","will","Veltari e os Guardiões do Universo","Veltari and the Guardians of the Universe","Vigia Partido","The Broken Sentinel","Núcleo de Vontade","Core of Will","Jade Estelar","Star Jade",8),
("odym","Odym","Azul","Blue","esperança","hope","Aelínos","Aelinos","Morrow","Morrow","Lágrima de Aurora","Aurora Tear","Pérola do Amanhã","Pearl of Tomorrow",5),
("okaara","Okaara","Laranja","Orange","avareza","avarice","Ghallos","Ghallos","Mammok","Mammok","Âmbar Primordial","Primordial Amber","Âmbar da Posse","Amber of Possession",12),
("ysmault","Ysmault","Vermelha","Red","fúria","rage","Brakkari","Brakkari","Vorgath","Vorgath","Coração de Vorgath","Heart of Vorgath","Ira Bruta","Raw Wrath",16),
("zamaron","Zamaron","Violeta","Violet","amor","love","Zaëlith","Zaëlith","Nyrielle","Nyrielle","Coração de Nyrielle","Heart of Nyrielle","Cristal Devoto","Devoted Crystal",20),
("korugar","Korugar","Amarela","Yellow","medo","fear","Skrell'Vath","Skrell'Vath","Thessara","Thessara","Coroa de Pavor","Crown of Dread","Fragmento de Pavor","Dread Shard",25),
("nok","Nok","Índigo","Indigo","compaixão","compassion","Ves'Kai","Ves'Kai","Penitente Sem Rosto","The Faceless Penitent","Coração do Penitente","Heart of the Penitent","Lágrima Índigo","Indigo Tear",30),
("ryut","Ryut","Negra","Black","morte","death","Silentes e o Coletor","Silent Ones and the Collector","Devorador de Ecos","Echo Devourer","Núcleo do Fim","Core of the End","Obsidiana do Fim","End Obsidian",32)]
import unicodedata
def lp(s):
    s=unicodedata.normalize('NFD',s); return ''.join(c for c in s if unicodedata.category(c)!='Mn').lower().replace("'"," ")
for (id,nome,cpt,cen,ept,een,rpt,ren,bpt,ben,dpt,den,mpt,men,nv) in P:
    rit_pt=L_pt.get(f"ritual.lanterna.{id}.rule",""); rit_en=L_en.get(f"ritual.lanterna.{id}.rule","")
    chaves=[lp(nome),"planeta "+lp(nome),lp(rpt.split(" e ")[0]),lp(bpt),lp(dpt),lp(ben),lp(den),lp(ren.split(" and ")[0])]
    chaves=[c for c in dict.fromkeys(chaves) if c]
    E.append({"id":"planeta_"+id,"chaves":chaves,
      "pt":f"{nome}: planeta da Tropa {cpt} ({ept}). Povo: {rpt}. Chefe: {bpt}, que dropa {dpt}. Minério: {mpt}. O anel de {nome} se forja a partir do nível {nv}. {rit_pt}",
      "en":f"{nome}: planet of the {cen} Corps ({een}). People: {ren}. Boss: {ben}, who drops {den}. Ore: {men}. The {nome} ring can be forged from level {nv}. {rit_en}"})
E.append({"id":"planeta_genese","chaves":["genese","genesis","nulo","the null","altar da vida","altar of life","brotos"],
 "pt":"Gênese é o planeta escondido da Vida. Ele só aparece quando você junta os sete anéis e os sete drops dos chefes. Lá ficam o Altar da Vida, onde se funde o Anel Branco, e a rachadura do Nulo, o chefe final da linha principal.",
 "en":"Genesis is the hidden planet of Life. It only appears when you gather the seven rings and the seven boss drops. There you find the Altar of Life, where the White Ring is fused, and the rift of the Null, the final boss of the main line."})
json.dump(E,open('src/main/resources/assets/lanterna/anel/duvidas.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
print(len(E))
